contract InvMutTest {
    C c;

    constructor() { c = new C(address(this), 0); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint256 amount, uint256 diff) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (amount)); require(amount <= 1000000000000000000000000000000);
        require(address(this).balance >= amount);
        require(amount > 0);

        c.AdjustBetAmounts(amount); if (__ESBMC_reverted()) return;
        c.AdjustDifficulty(diff); if (__ESBMC_reverted()) return;
        c.OpenToThePublic(); if (__ESBMC_reverted()) return;

        c.wager{value: amount}(); if (__ESBMC_reverted()) return;
        c.play(); if (__ESBMC_reverted()) return;

        uint256 bal = address(c).balance;
        uint256 pot = c.winnersPot(); if (__ESBMC_reverted()) return;

        assert(pot == bal / 2);
    }

    receive() external payable {}
}

