pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {PoCGame} from "../src/PoCGame.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    PoCGame c;

    function setUp() public {
        c = new PoCGame(address(this), 0);
    }

    function _run(uint256 amount, uint256 diff) internal {
        amount = bound(amount, 0, 1000000000000000000000000000000);
        vm.deal(address(this), VALUE_CAP);
        vm.deal(address(c), VALUE_CAP);
        vm.assume(address(this).balance >= amount);
        vm.assume(amount > 0);
        try c.AdjustBetAmounts(amount) {} catch { return; }
        try c.AdjustDifficulty(diff) {} catch { return; }
        try c.OpenToThePublic() {} catch { return; }
        try c.wager{value: amount}() {} catch { return; }
        try c.play() {} catch { return; }
        uint256 bal = address(c).balance;
        uint256 pot;
        try c.winnersPot() returns (uint256 __r) { pot = __r; } catch { return; }
        assertTrue(pot == bal / 2);
    }

    function testFuzz_run(uint256 amount, uint256 diff) public {
        _run(amount, diff);
    }

    receive() external payable {}
}
